# -*- coding: utf-8 -*-
"""Phan mo rong cua Module 04: vi dieu khien, he nhung va SoC (Floyd 14-8, 14-9, tr.838-845). Phuc vu muc tieu CO5 cua de cuong ('vi xu ly va vi dieu khien'). Khong co slide cua giang vien cho phan nay.
So lieu minh hoa tinh bang build/numlib/mcu.py (verify_m04_mcu.py tinh lai doc lap)."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'numlib'))
from hx import *
import mcu as M
def fig(path, alt, cap='', w=None):          # same markup as the other modules: .slide-fig keeps the image inside the column on a phone
    return f'<figure class="slide-fig"><img class="fig" src="{{R}}{path}" alt="{esc(alt)}" loading="lazy">' + (f'<figcaption class="srcnote">{cap}</figcaption>' if cap else '') + '</figure>'

def mcu(lang):
    vi = lang == 'vi'
    d = lambda x: f'{x:g}'.replace('.', ',') if vi else f'{x:g}'
    v_avg = M.pwm_avg(12, 2, 8); t32 = M.rollover_s(32, 1e6) / 60; a32 = M.addresses(32); tim = M.timer_s(16e6, 8, 2000) * 1000
    periph = [('GPIO (vào/ra đa dụng)', 'GPIO (general-purpose I/O)', 'đọc công tắc, điều khiển LED, chọn/cho phép chốt và bộ đệm; chỉ có thanh ghi điều khiển (vào hay ra) và thanh ghi dữ liệu', 'reads switches, drives LEDs, selects or enables latches and buffers; usually just a control register (input or output) and a data register'),
              ('Bộ điều khiển truyền thông', 'Communication controllers', 'UART, Ethernet, USB, I²C, SPI, CAN, HDLC; cấu hình phức tạp nhất vì thời gian, điều khiển luồng và định dạng dữ liệu khác nhau', 'UART, Ethernet, USB, I²C, SPI, CAN, HDLC; the most involved to configure because timing, flow control and data format differ'),
              ('Bộ định thời', 'Timers', 'đặt tốc độ truyền, báo hết khoảng thời gian định trước, đo thời gian giữa các sự kiện', 'set the communication rate, signal that a preset interval has elapsed, time the gap between events'),
              ('Bộ mã hoá vuông góc', 'Quadrature encoder', 'đếm lên/xuống theo mẫu mã hoá của cảm biến vị trí; bộ đếm 32 bit trở lên để khỏi tràn; mỗi chiều chuyển động cần một bộ', 'counts up or down with the pattern of a position sensor; counter of 32 bits or more so it cannot overflow; one encoder per dimension of movement'),
              ('Bộ điều chế độ rộng xung (PWM)', 'Pulse width modulator (PWM)', 'đổi chu kỳ làm việc của xung lặp để điều khiển tốc độ động cơ mà giữ nguyên biên độ', 'varies the duty cycle of a repetitive pulse to set motor speed while the amplitude stays fixed'),
              ('Bộ điều khiển bộ nhớ ngoài', 'External memory controller', 'cho nối thêm SRAM, SDRAM, flash khi bộ nhớ trong không đủ; có chân chọn chip, độ rộng cổng 8/16/32 bit, số trạng thái chờ', 'attaches extra SRAM, SDRAM or flash when internal memory is not enough; chip-select lines, 8/16/32-bit port width, number of wait states'),
              ('ADC và DAC', 'ADCs and DACs', 'đưa tín hiệu tương tự vào và ra (cảm biến, loa, điều khiển)', 'bring analogue signals in and out (sensors, audio, control)')]
    if vi:
        h = '<h3 id="mcu">Phần mở rộng: vi điều khiển, hệ nhúng và SoC (Floyd 14-8, 14-9)</h3><p class="srcnote">Phần này không có slide của giảng viên; dựng từ Floyd Chương 14 mục 14-8 và 14-9 (tr.838 đến 845) để đáp ứng mục tiêu CO5 (hệ máy tính, vi xử lý và vi điều khiển). Trong ngân hàng: 30 câu gốc (15 Đúng/Sai và 15 Self-Test của Floyd Chương 14), 24 câu bổ sung tính bằng chương trình và 9 bài tự luận gốc (Checkup 14-8, 14-9). Hai khoá in của sách (Đúng/Sai 12 và Self-Test 13) mâu thuẫn với chính văn bản; site dùng đáp án đúng và ghi rõ trong nhãn nguồn.</p>'
        h += '<p>Bộ vi xử lý đa dụng nối được nhiều thiết bị qua các bus hệ thống nhưng giao tiếp với thế giới thực thì hạn chế: phải thêm ADC, DAC, UART, bộ định thời ngoài. <b>Vi điều khiển</b> (µC, MCU) gộp <b>lõi vi xử lý, bộ nhớ và các ngoại vi thông dụng trong một vỏ</b>; dùng trong <b>hệ nhúng</b>, là hệ chạy một số nhiệm vụ xác định với cả phần cứng lẫn phần sụn (firmware) cần thiết.</p>'
        h += fig('assets/figs/m04/mcu_block_vi.png', 'Sơ đồ khối vi điều khiển', 'Hình: sơ đồ khối giản lược của một vi điều khiển (tự vẽ lại theo ý Floyd Hình 14–34).')
        h += ul(['<b>Lõi xử lý</b> (processor core).', '<b>Bộ nhớ không khả biến</b> (ROM, flash) cho mã chương trình và cấu hình giữ được khi mất điện; <b>RAM</b> cho dữ liệu, thanh ghi trong và bộ đệm ngoại vi.', '<b>Ngoại vi</b>: bộ định thời, ADC, DAC, bộ điều khiển truyền thông, cổng vào/ra.', '<b>Bus trong</b> nối lõi với bộ nhớ và với ngoại vi, cùng mạch giao tiếp với thiết bị ngoài.', 'Loại cao cấp còn có vòng khoá pha (PLL) nhân tần số xung nhịp, bộ điều khiển DMA, tài nguyên logic khả trình, giao diện JTAG để thử và nạp chương trình, và các chế độ tiết kiệm điện.'])
        h += '<h4>Các ngoại vi thường gặp</h4>' + table(['Ngoại vi', 'Dùng để'], [[a, c] for a, _, c, _ in periph])
        h += '<p><b>Chân đa chức năng.</b> Nhiều chân của vi điều khiển làm được nhiều việc (chân truyền USB, chân UART, chân địa chỉ bus ngoài, hay GPIO) nhưng tại một thời điểm chỉ một chức năng, và thiết kế cố định chức năng từng chân. Ưu điểm: bớt số chân và kích thước. Nhược điểm: không dùng đồng thời mọi tính năng; có thể cần mạch ngoài hoặc chọn vi điều khiển có nhiều bản sao của một ngoại vi.</p>'
        h += '<p><b>Cấu hình ngoại vi</b> là nạp các <b>thanh ghi</b> của ngoại vi: thanh ghi điều khiển (chế độ, chiều vào/ra), thanh ghi trạng thái (cờ xong, cờ lỗi; phần sụn phải xoá cờ để ngoại vi làm tiếp) và thanh ghi dữ liệu (giá trị nạp trước, giá trị đếm hiện tại). Công cụ đồ hoạ có thể sinh mã khởi tạo C/C++, nhưng lập trình viên vẫn phải rà lại mã.</p>'
        h += '<h4>Vi điều khiển trong hệ nhúng</h4>' + ul(['<b>Thiết bị cầm tay</b> (điện thoại, máy tính bỏ túi, GPS): thường dùng lõi ARM; máy tính bỏ túi có ROM chứa mã, RAM, cổng USB, bàn phím nối qua các đường GPIO, màn hình LCD qua bộ điều khiển LCD, một bộ định thời tự tắt máy để tiết kiệm điện.', '<b>Đồ gia dụng</b>: lò vi sóng, máy giặt, tủ lạnh, robot hút bụi.', '<b>Ô tô</b>: động cơ, nhiên liệu, phanh, túi khí, khoá cửa, hiển thị; vi điều khiển phải chịu nhiệt độ, độ ẩm, rung và nhiễu điện của xe.', '<b>Tự động hoá và robot</b>: điều khiển chuyển động bằng phản hồi; khi khởi động dùng bộ mã hoá vuông góc và PWM đưa cơ cấu về vị trí gốc rồi xoá bộ đếm; hệ ba trục dùng ba bộ.'])
        h += '<h4>Hệ trên chip (SoC)</h4><p>SoC là <b>mạch tích hợp gộp mọi thành phần của một hệ máy tính hay hệ điện tử trên một chip</b>: một hay nhiều lõi CPU, bộ xử lý tín hiệu số (DSP), bộ xử lý đồ hoạ (GPU), bộ nhớ, ADC và DAC, giao diện I/O (USB, I²C, USART), nguồn định thời (dao động, PLL), quản lý nguồn, cầu nối bus, ngoại vi và logic khả trình. Ưu điểm chính: kích thước nhỏ và công suất thấp, nên hợp điện thoại, máy tính bảng, máy ảnh số. Vi điều khiển thường được coi là SoC có chức năng hạn chế; SoC hay dùng lõi ARM (kiến trúc RISC, hiệu năng cao và tiêu thụ điện thấp).</p>'
        h += '<h4>Số liệu minh hoạ (tính bằng chương trình)</h4>' + ul([f'Bus địa chỉ 32 bit đánh địa chỉ 2³² = {a32:,} vị trí, tức 4 GiB nếu mỗi vị trí 1 byte.'.replace(',', ' '), f'PWM biên độ 12 V, mức cao 2 ms trong chu kỳ 8 ms: D = 25 %, điện áp trung bình {d(v_avg)} V (đổi D thành 50 % hay 75 % thì được 6 V và 9 V).', f'Bộ định thời chạy xung nhịp 16 MHz, chia trước 8, đếm 2 000 xung: 2 000 × 8 / 16 MHz = {d(tim)} ms.', f'Bộ đếm 32 bit của bộ mã hoá vuông góc đếm 1 MHz tràn sau 2³² / 10⁶ ≈ {d(round(t32, 1))} phút; ở 1 kHz thì khoảng 49,7 ngày, nên 32 bit đủ cho hầu hết ứng dụng.'])
        h += fig('assets/figs/m04/pwm_duty_vi.png', 'Dạng sóng PWM với ba chu kỳ làm việc', 'Hình: ba chu kỳ làm việc của một tín hiệu PWM 12 V, chu kỳ 4 ms, và điện áp trung bình tương ứng (tính bằng mcu.py).')
    else:
        h = '<h3 id="mcu">Extension: microcontrollers, embedded systems and SoC (Floyd 14-8, 14-9)</h3><p class="srcnote">There are no lecturer slides for this part; it is built from Floyd Chapter 14, sections 14-8 and 14-9 (pp.838 to 845), to meet outcome CO5 (computer system, microprocessor and microcontroller). In the bank: 30 original questions (the 15 True/False and 15 Self-Test items of Floyd Chapter 14), 24 added questions computed by program and 9 original written problems (Checkups 14-8, 14-9). Two printed keys of the book (True/False 12 and Self-Test 13) contradict its own text; the site uses the correct answer and says so in the source label.</p>'
        h += '<p>A general-purpose microprocessor can interface with many devices over its system buses, but its link to the real world is limited: it needs ADCs, DACs, UARTs and external timers. A <b>microcontroller</b> (µC, MCU) puts a <b>processor core, memory and the common peripherals in one package</b>; it is used in <b>embedded systems</b>, which perform a specific set of tasks with the hardware and firmware needed for them.</p>'
        h += fig('assets/figs/m04/mcu_block_en.png', 'Block diagram of a microcontroller', 'Figure: simplified block diagram of a microcontroller (redrawn after the idea of Floyd Figure 14–34).')
        h += ul(['<b>Processor core.</b>', '<b>Nonvolatile memory</b> (ROM, flash) for program code and configuration data that must survive power-off; <b>RAM</b> for data, internal registers and peripheral buffers.', '<b>Peripherals</b>: timers, ADCs, DACs, communication controllers, I/O ports.', '<b>Internal buses</b> joining the core to memory and to the peripherals, and interface circuitry to external devices.', 'More capable parts add a phase-locked loop (PLL) that multiplies the clock, DMA controllers, programmable-logic fabric, a JTAG interface for test and programming, and low-power modes.'])
        h += '<h4>Common peripherals</h4>' + table(['Peripheral', 'Used for'], [[b, dd] for _, b, _, dd in periph])
        h += '<p><b>Multifunction pins.</b> Many pins can serve several functions (a USB transmit line, a UART line, an external-bus address line or a GPIO) but only one at a time, and the design fixes each pin\'s function. Advantage: fewer pins and a smaller package. Disadvantage: not every feature can be used together; external circuits may be needed or a part with several instances of a peripheral must be chosen.</p>'
        h += '<p><b>Configuring a peripheral</b> means loading its <b>registers</b>: control registers (mode, input or output), status registers (done and error flags; firmware must clear a flag so the peripheral can continue) and data registers (preloaded value, current count). Visual tools can generate C/C++ initialisation code, but the programmer must still review it.</p>'
        h += '<h4>Microcontrollers in embedded systems</h4>' + ul(['<b>Handheld devices</b> (phones, calculators, GPS): often ARM cores; a calculator has a ROM holding the code, RAM, a USB port, a keypad on GPIO lines, an LCD through an LCD-driver peripheral and a timer that powers it down to save energy.', '<b>Consumer appliances</b>: microwave ovens, washing machines, refrigerators, robot vacuum cleaners.', '<b>Automobiles</b>: engine, fuel, brakes, air bags, door locks, displays; the microcontroller must survive the temperature, humidity, vibration and electrical noise of a vehicle.', '<b>Automation and robotics</b>: motion control by feedback; at power-up the quadrature encoder and PWM drive the mechanism to its home position and clear the counter; a three-axis system uses three.'])
        h += '<h4>System on chip (SoC)</h4><p>A SoC is an <b>integrated circuit that combines all components of a computer or other electronic system on a single chip</b>: one or more CPU cores, a digital signal processor (DSP), a graphics processor (GPU), memory, ADC and DAC, I/O interfaces (USB, I²C, USART), timing sources (oscillators, PLLs), power management, bus bridges, peripherals and programmable logic. The main advantages are small size and low power, which suit phones, tablets and digital cameras. A microcontroller is often regarded as a SoC with limited functionality; SoCs commonly use ARM cores (RISC architecture, high performance with low power).</p>'
        h += '<h4>Worked numbers (computed by program)</h4>' + ul([f'A 32-bit address bus addresses 2³² = {a32:,} locations, i.e. 4 GiB if each location holds one byte.', f'A 12 V PWM, HIGH for 2 ms in an 8 ms period: D = 25 %, average voltage {d(v_avg)} V (D = 50 % or 75 % gives 6 V and 9 V).', f'A timer on a 16 MHz clock, prescaler 8, counting 2,000 pulses: 2,000 × 8 / 16 MHz = {d(tim)} ms.', f'A 32-bit quadrature-encoder counter at 1 MHz overflows after 2³² / 10⁶ ≈ {d(round(t32, 1))} minutes; at 1 kHz it takes about 49.7 days, so 32 bits is enough for most applications.'])
        h += fig('assets/figs/m04/pwm_duty_en.png', 'PWM waveforms at three duty cycles', 'Figure: three duty cycles of a 12 V PWM signal with a 4 ms period and the corresponding average voltage (computed with mcu.py).')
    return h
